describe("services/search-service", () => {
  it("indexes an issue and a comment on creation", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zulu index target" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee index target",
      parentId: null,
      mentionedUserIds: [],
    });

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zulu",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.total).toBe(1);
    expect(issueHits.items[0]).toMatchObject({ kind: "issue", id: issue.id });

    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Yankee",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.total).toBe(1);
    expect(commentHits.items[0]).toMatchObject({ kind: "comment", id: comment.id });
  });

  it("re-indexes an updated issue in place", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Original Title Marker" }),
    );

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Updated Title Marker",
    });

    const stale = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Original Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(stale.total).toBe(0);

    const fresh = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Updated Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(fresh.total).toBe(1);
    expect(fresh.items[0]).toMatchObject({ id: issue.id });
  });

  it("drops an archived issue from the index", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveIndexMarker" }),
    );

    const before = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(before.total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const after = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(after.total).toBe(0);
  });

  it("never returns another tenant's rows", async () => {
    const other = await createTenant("searchsvcother", "growth");
    await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "CrossTenantMarker" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "CrossTenantMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });

    expect(hits.total).toBe(0);
    expect(hits.items).toHaveLength(0);
  });

  it("falls back to plain matching when advanced_search is off", async () => {
    // The tenant is on "growth", which does not include advanced_search.
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "PlainMatchWorks" }),
    );

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).resolves.toMatchObject({ total: 1 });

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "status:PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/not included in this plan/);
  });

  it("rate-limits search queries per organization", async () => {
    rateLimitState.allowed = false;

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "anything",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/rate limit/i);
  });
});

/**
 * Soft-delete filtering.
 *
 * Archived rows stay in the table and disappear from every default read. The
 * cases below pin both halves of that: an archived issue is invisible unless
 * `includeArchived` is set, and archiving a project cascades to its issues.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let live: Issue;
let archived: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("softdelete");

  live = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
  );

  const doomed = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Archived away" }),
  );

  archived = await issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    doomed.id,
  );
});

afterAll(() => {
  cleanup();
});

describe("archived issues", () => {
  it("marks the row rather than deleting it", async () => {
    expect(archived.archivedAt).not.toBeNull();

    const stillThere = await issueRepo.findIssueById(
      tenant.org.id,
      archived.id,
    );
    expect(stillThere?.id).toBe(archived.id);
  });

  it("is excluded from the default listing", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toEqual([live.id]);
    expect(page.total).toBe(1);
  });

  it("reappears when the caller opts in", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });

    expect(page.total).toBe(2);
    expect(page.items.map((issue) => issue.id).sort()).toEqual(
      [live.id, archived.id].sort(),
    );
  });

  it("is excluded from the per-project count the quota reads", async () => {
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(1);

    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(2);
  });

  it("is excluded from the board columns", async () => {
    const columns = await issueRepo.listBoardColumns(
      tenant.org.id,
      tenant.project.id,
    );
    const ids = columns.flatMap((column) => column.issues.map((i) => i.id));

    expect(ids).toEqual([live.id]);
  });

  it("keeps its issue number reserved", async () => {
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(3);
  });

  it("refuses to be archived twice", async () => {
    await expect(
      issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        archived.id,
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("archiving a project", () => {
  it("cascades to the project's live issues", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch",
      slug: "scratch",
      key: "SCR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Doomed with project" }),
    );

    const result = await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: true,
    });

    expect(result.archivedAt).not.toBeNull();
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id),
    ).resolves.toBe(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(1);

    const listed = await projectRepo.listProjects({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map((project) => project.id)).not.toContain(scratch.id);
  });
});
/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
