/** Includes imported rows as well as numbers retired by moves or deletion. */
function lastIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const counter = getDb()
    .select()
    .from(issueNumberCounters)
    .where(
      and(
        orgPredicate(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, counter?.lastNumber ?? 0);
}

/** Called in the same transaction as the write that issues or retires a number. */
function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  lastNumber: number,
): void {
  getDb()
    .insert(issueNumberCounters)
    .values({ orgId, projectId, lastNumber })
    .onConflictDoUpdate({
      target: [issueNumberCounters.orgId, issueNumberCounters.projectId],
      set: {
        lastNumber: sql`max(${issueNumberCounters.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

/** The next number follows the highest ever issued in this project. */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return lastIssueNumber(orgId, projectId) + 1;
}

