export async function relocateIssue(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  const row = db.transaction(() => {
    const current = db
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);
    if (current.projectId === projectId) return current;

    const fromProjectId = current.projectId as ProjectId;
    rememberIssueNumber(orgId, fromProjectId, lastIssueNumber(orgId, fromProjectId));
    const number = lastIssueNumber(orgId, projectId) + 1;
    const moved = db
      .update(issues)
      .set({ projectId, number, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
    if (!moved) throw new Error(`Issue ${issueId} not found`);

    rememberIssueNumber(orgId, projectId, number);
    return moved;
  });

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

